using System;
using System.Linq;
using Microsoft.EntityFrameworkCore;

namespace App.Data;

public class UserRepository
{
    private readonly AppDbContext _db;

    public UserRepository(AppDbContext db)
    {
        _db = db;
    }

    public IEnumerable<User> GetById(int page, int pageSize)
    {
        return _db.Users.Skip(page * pageSize).Take(pageSize + 1);
    }
}

